        + `<div style="position:absolute;left:50%;top:${o.vf.y || 34}%;width:120px;height:90px;transform:translate(-50%,-50%);border:2px solid #7dff6a;box-shadow:0 0 0 1px rgba(0,0,0,.4)"></div>`
