  // a tram stop: a shelter with the stop's name on its roof (read from above)
  function shelter(p, txt = 'POSTAJA') { const grp = new THREE.Group(); const rf = box(2.6, 0.18, 6.0, M(0x2a5aa8)); rf.position.y = 2.6; grp.add(rf); for (const [x, z] of [[-2.8, -1.1], [2.8, -1.1], [-2.8, 1.1], [2.8, 1.1]]) { const po = box(0.12, 2.6, 0.12, M(0x9aa3ad)); po.position.set(x, 1.3, z); grp.add(po); }
    const back = box(0.06, 1.8, 5.6, new THREE.MeshLambertMaterial({ color: 0xbfd8ff, transparent: true, opacity: 0.45 })); back.position.set(0, 1.4, 1.2); grp.add(back);
    const sg = new THREE.Mesh(new THREE.PlaneGeometry(5.6, 1.6), new THREE.MeshBasicMaterial({ map: signTex(txt, null, '#2a5aa8', 1024, 288) })); sg.rotation.x = -Math.PI / 2; sg.rotation.z = 0; sg.position.y = 2.71; grp.add(sg); return place(grp, p, 0); }
  // ---- road train, loaded jeep, convoy
  // a car's model measured in its own frame (forward along x; the lights' glow, sprites and big flat helpers left out)
  function carBox(c) {
    const v = Render.viewOf(c), g2 = v.grp, r = g2.rotation.clone(), p0 = g2.position.clone(), s0 = g2.scale.clone();
    g2.rotation.set(0, 0, 0); g2.position.set(0, 0, 0); g2.scale.set(1, 1, 1); g2.updateMatrixWorld(true);
    const bb = new THREE.Box3(), tmp = new THREE.Box3(), sz = new THREE.Vector3();
    g2.traverse(o => { if (!o.isMesh || !o.visible || !o.geometry) return; const om = Array.isArray(o.material) ? o.material[0] : o.material; if (om && (om.transparent || om.blending === THREE.AdditiveBlending)) return;
      if (!o.geometry.boundingBox) o.geometry.computeBoundingBox(); tmp.copy(o.geometry.boundingBox).applyMatrix4(o.matrixWorld); tmp.getSize(sz); if (Math.max(sz.x, sz.y, sz.z) > 16 || sz.y < 0.02) return; bb.union(tmp); });
    g2.rotation.copy(r); g2.position.copy(p0); g2.scale.copy(s0); g2.updateMatrixWorld(true);
    return { x0: bb.min.x, x1: bb.max.x, z0: bb.min.z, z1: bb.max.z, y0: bb.min.y, y1: bb.max.y };
  }
  // a car's model and paint changed (its view built again: Render.attachRace)
  function remodel(list) { const Ms = Core.MODELS; for (const [c, id, col] of list) { if (id) { const m = Ms.find(q => q.id === id); if (m) c.m = m; } if (col != null) c.color = col; } Render.attachRace(R()); frames(3); }
  const barkM = () => [M(0x6b4a2e), M(0xdcbc8c), M(0xdcbc8c)];
  function logMesh(L, r = 0.27) { const g3 = new THREE.CylinderGeometry(r * (0.9 + rnd() * 0.2), r, L, 12); g3.rotateZ(Math.PI / 2); const m = new THREE.Mesh(g3, barkM()); m.castShadow = true; return m; }
  // a timber trailer (length along x, its middle at 0), loaded with fill (0..1) of its logs; tail: n logs left only (on the back bunk)
  function logTrailer(L = 13, fill = 1, dolly = true) {
    const grp = new THREE.Group(), steel = M(0x2b2f33), red = M(0xb8261f);
    const deck = box(2.5, 0.28, L, steel); deck.position.y = 1.25; grp.add(deck); const rail = box(2.56, 0.18, L, red); rail.position.y = 1.1; grp.add(rail);
    const ax = dolly ? [L / 2 - 1.3, L / 2 - 2.6, -L / 2 + 1.4, -L / 2 + 2.7, -L / 2 + 4.0] : [-L / 2 + 1.4, -L / 2 + 2.7, -L / 2 + 4.0];
    for (const x of ax) for (const z of [-1.05, 1.05]) grp.add(whl(0.52, 0.5, x, 0.52, z));
    const sec = 2, secL = (L - 0.8) / sec, rows = [4, 4, 3, 2], logs = [];
    for (let k = 0; k < sec; k++) { const cx = -L / 2 + 0.4 + secL * (k + 0.5);
      for (const x of [cx - secL / 2 + 0.25, cx + secL / 2 - 0.25]) for (const z of [-1.18, 1.18]) { const st = box(0.14, 2.3, 0.14, red); st.position.set(x, 1.25 + 1.15, z); grp.add(st); }
      rows.forEach((n, j) => { for (let i = 0; i < n; i++) logs.push({ x: cx + (rnd() - 0.5) * 0.25, y: 1.39 + 0.27 + j * 0.47, z: (i - (n - 1) / 2) * 0.56, L: secL - 0.1 - rnd() * 0.3, k }); });
    }
    const keep = Math.round(logs.length * fill); logs.sort((a, b) => a.y - b.y || b.k - a.k);
    logs.slice(0, keep).forEach(q => { const m = logMesh(q.L); m.position.set(q.x, q.y, q.z); grp.add(m); });
    if (dolly) { const bar = box(0.2, 0.2, 2.6, steel); bar.position.set(L / 2 + 1.2, 0.85, 0); grp.add(bar); }
    return grp;
  }
  // the player's car as the tractor of a road train: trailers (lengths Ls, fills) one behind the other along the road
  // a copy of the player's car (with all it carries) dd metres further down the road, turned with the road; the player's own one hidden
  // the player stopped (no more dust or flame from its wheels and exhaust) and the views built afresh
  function calm() { const P0 = P(); P0.vx = P0.vz = 0; Render.attachRace(R()); frames(2); }
  function aheadCopy(dd) { const P0 = P(), v = Render.viewOf(P0), k = cloneCar(P0, dd, 0, false), a0 = at(P0.dist), a1 = at(P0.dist + dd); k.rotation.y += -(a1.hd - a0.hd); const gy = groundAt(k.position.x, k.position.z); if (gy != null) k.position.y = Math.max(k.position.y, gy); v.grp.scale.setScalar(0.001); return k; }
  // (dd: the whole train dd metres further down the road than the player, whose own car is hidden: a copy of it pulls the train)
  function roadTrain(Ls = [13, 13], fills = [1, 1], gap = 3.2, dd = 0) {
    const P0 = P(), b = carBox(P0), v = Render.viewOf(P0), lat = latOf(P0), tail = -b.x0, out = [];
    if (dd) { const k = cloneCar(P0, dd, 0, false), a0 = at(P0.dist), a1 = at(P0.dist + dd); k.rotation.y += -(a1.hd - a0.hd); const gy = groundAt(k.position.x, k.position.z); if (gy != null) k.position.y = Math.max(k.position.y, gy); v.grp.scale.setScalar(0.001); out.head = k; }
    let d = P0.dist + dd - tail * v.grp.scale.x - gap; if (dd) d = P0.dist + dd - tail - gap;
    Ls.forEach((L, k) => { const dC = d - L / 2, q = at(dC, lat), t = logTrailer(L, fills[k], true); t.position.set(q.x, (q.y || 0) + (P0.y - at(P0.dist).y || 0) * 0, q.z); t.position.y = groundAt(q.x, q.z) != null ? Math.max(q.y, groundAt(q.x, q.z) - 0.05) : q.y; t.rotation.y = -q.hd; add(t); out.push({ grp: t, d: dC, q }); d = dC - L / 2 - gap; });
    return out;
  }
  // a loose log: on the road (fly: in the air, turning)
  function looseLog(p, fly = 0, L = 5.6) { const m = logMesh(L); m.position.set(p.x, p.y + 0.28 + fly, p.z); m.rotation.set(fly ? rnd() * 1.2 - 0.6 : 0, -(p.hd || 0) + (rnd() - 0.5) * (fly ? 2.5 : 1.6), fly ? rnd() * 1.4 - 0.7 : 0); return add(m); }
  // a pile of logs by the road (a timber yard)
  function logPile(p, n = 5, L = 6) { const grp = new THREE.Group(); for (let j = 0; j < n; j++) for (let i = 0; i < n - j; i++) { const m = logMesh(L, 0.3); m.position.set(0, 0.3 + j * 0.52, (i - (n - j - 1) / 2) * 0.62); grp.add(m); } return place(grp, p); }

  // supplies: crates, jerrycans, sacks, rolled tents (olive, sand, dark green)
  const SUP = [0x55602f, 0x3f4a25, 0x6b6f3a, 0xb59a6a, 0x2f3a22];
  function supply(kind, col) { const m = M(col);
    if (kind === 0) { const g3 = new THREE.Group(); const b2 = box(0.62, 0.5, 0.9, m); g3.add(b2); const r = box(0.64, 0.08, 0.92, M(0x2a2a20)); r.position.y = 0.12; g3.add(r); return g3; }
    if (kind === 1) return box(0.22, 0.5, 0.36, M(0x4f5a2a));
    if (kind === 2) { const s2 = new THREE.Mesh(new THREE.SphereGeometry(0.34, 10, 8), M(0xb59a6a)); s2.scale.set(1.5, 0.7, 1); return s2; }
    const t = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 1.3, 10), m); t.rotation.x = Math.PI / 2; return t; }
  // a load on a car's roof (its own group: it moves with the car), fill 0..1; trailer: a small one behind with more
  function loadCar(c, fill = 1, opts = {}) {
    const v = Render.viewOf(c), b = carBox(c), grp = new THREE.Group(), x0 = b.x0 + 0.35, x1 = b.x1 - (opts.front || 1.3), z0 = b.z0 + 0.12, z1 = b.z1 - 0.12;
    const items = []; for (let j = 0; j < 3; j++) for (let x = x0 + 0.45; x < x1 - 0.2; x += 0.95) for (let z = z0 + 0.35; z < z1 - 0.2; z += 0.68) items.push({ x: x + (rnd() - 0.5) * 0.1, y: b.y1 + 0.25 + j * 0.52, z, j });
    const keep = Math.max(opts.min || 0, Math.round(items.length * fill)); items.sort((a, q) => a.j - q.j);
    items.slice(0, keep).forEach((q, i) => { const k = q.j === 2 && i % 3 === 0 ? 3 : q.j === 2 && i % 3 === 1 ? 2 : i % 5 === 4 ? 1 : 0; const s2 = supply(k, SUP[i % SUP.length]); s2.position.set(q.x, q.y + (k === 1 ? 0 : k === 3 ? -0.03 : 0), q.z); s2.rotation.y += (rnd() - 0.5) * 0.3; grp.add(s2); });
    if (fill > 0.6) { const net = box(z1 - z0 + 0.1, 0.03, x1 - x0, new THREE.MeshLambertMaterial({ color: 0x2a3018, transparent: true, opacity: 0.55 })); net.position.set((x0 + x1) / 2, b.y1 + 0.25 + 3 * 0.52 - 0.05, (z0 + z1) / 2); grp.add(net); }
    v.grp.add(grp); return grp;
  }
  // a small two-wheeled trailer behind a car (fill: its load)
  function cartBehind(c, fill = 1, col = 0x55602f) {
    const b = carBox(c), v = Render.viewOf(c), lat = latOf(c), q = at(c.dist - (-b.x0) * v.grp.scale.x - 2.6, lat), grp = new THREE.Group();
    const bed = box(1.7, 0.7, 2.6, M(col)); bed.position.y = 0.9; grp.add(bed); grp.add(whl(0.42, 0.3, 0, 0.42, 0.95), whl(0.42, 0.3, 0, 0.42, -0.95)); const bar = box(0.12, 0.12, 1.6, M(0x222222)); bar.position.set(2.0, 0.65, 0); grp.add(bar);
    const n = Math.round(9 * fill); for (let i = 0; i < n; i++) { const s2 = supply(i % 4 === 3 ? 2 : 0, SUP[(i * 2) % SUP.length]); s2.position.set(-0.85 + (i % 3) * 0.85, 1.5 + Math.floor(i / 3) * 0.5, ((i % 2) - 0.5) * 0.6); grp.add(s2); }
    if (fill > 0.6) { const tarp = box(1.8, 0.06, 2.7, M(0x3f4a25)); tarp.position.y = 1.5 + Math.ceil(n / 3) * 0.5 - 0.2; grp.add(tarp); }
    grp.position.set(q.x, groundAt(q.x, q.z) != null ? Math.max(q.y, groundAt(q.x, q.z)) : q.y, q.z); grp.rotation.y = -q.hd; return add(grp);
  }
  // a fallen or flying piece of the load (kind: 0 crate, 1 jerrycan, 2 sack, 3 tent)
  function dropped(p, fly = 0, kind = 0) { const s2 = supply(kind, SUP[(rnd() * SUP.length) | 0]); s2.scale.setScalar(1.7); s2.position.set(p.x, p.y + 0.45 + fly, p.z); s2.rotation.set(fly ? rnd() * 2 : 0, rnd() * 6, fly ? rnd() * 2 : (rnd() - 0.5) * 0.3); return add(s2); }
  function soldier(p, sc = 1.3, col = 0x55602f, capC = 0x3f4a25, pack = true) { const g2 = new THREE.Group(); const body = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.3, 1.1, 10), M(col)); body.position.y = 1.15; g2.add(body); const hd = new THREE.Mesh(new THREE.SphereGeometry(0.17, 10, 8), M(0xd8b090)); hd.position.y = 1.85; g2.add(hd); const cap = new THREE.Mesh(new THREE.SphereGeometry(0.2, 10, 6, 0, 6.3, 0, 1.6), M(capC)); cap.position.y = 1.9; g2.add(cap); for (const z of [-0.12, 0.12]) { const lg = box(0.14, 0.7, 0.14, M(capC === 0xf4f4f0 ? col : capC)); lg.position.set(0, 0.35, z); g2.add(lg); } if (pack) { const pk = box(0.36, 0.55, 0.3, M(0x6b6f3a)); pk.position.set(-0.28, 1.25, 0); g2.add(pk); } g2.scale.setScalar(sc); return place(g2, p, p.face != null ? p.face : rnd() * 6); }
  function tent(p, col = 0x55602f, sc = 1) { const g3 = new THREE.CylinderGeometry(0.01, 2.2, 2.2, 3, 1); const m = new THREE.Mesh(g3, M(col)); m.rotation.z = Math.PI / 2; m.rotation.y = 0; const grp = new THREE.Group(); m.scale.set(1, 1.8, 1); m.position.y = 1.0; m.rotation.set(0, 0, 0); const pr = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 1.6, 3.6, 3, 1, false), M(col)); pr.rotation.x = Math.PI / 2; pr.rotation.y = 0; pr.position.y = 0.8; grp.add(pr); grp.scale.setScalar(sc); return place(grp, p, rnd()); }
  // convoy pieces: a police motorbike, a drone, a red carpet, a flag
  function policeMoto(p, sc = 1.8) { const g2 = VEH.moto(); g2.traverse(o => { if (o.isMesh && o.material.color && o.material.color.getHex() === 0xd8282a) o.material = M(0xf4f4f0); }); const lb = box(0.3, 0.12, 0.12, new THREE.MeshBasicMaterial({ color: 0x2f6bff })); lb.position.set(-0.6, 1.35, 0); g2.add(lb); const st = box(0.42, 0.1, 0.5, M(0x2a5aa8)); st.position.set(0.1, 0.7, 0); g2.add(st); g2.scale.setScalar(sc); const h = new THREE.Group(); h.add(g2); h.position.set(p.x, p.y, p.z); h.rotation.y = -(p.hd || 0); return add(h); }
  function drone(p, sc = 2.2) { const g2 = new THREE.Group(), blk = M(0x1c1c1c); const b2 = box(0.5, 0.18, 0.5, blk); g2.add(b2); for (const [x, z] of [[0.45, 0.45], [0.45, -0.45], [-0.45, 0.45], [-0.45, -0.45]]) { const arm = box(0.06, 0.06, 0.7, blk); arm.position.set(x / 2, 0, z / 2); arm.rotation.y = Math.atan2(z, x); g2.add(arm); const r = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.28, 0.02, 16), new THREE.MeshBasicMaterial({ color: 0x9aa3ad, transparent: true, opacity: 0.5 })); r.position.set(x, 0.1, z); g2.add(r); } const led = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff2a2a })); led.position.set(0.25, -0.05, 0); g2.add(led); const cam = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), M(0x2a2a2a)); cam.position.y = -0.15; g2.add(cam); g2.scale.setScalar(sc); g2.position.set(p.x, p.y, p.z); return add(g2); }
  function carpet(p, L = 16, W = 2.2, face = 0) { const m = box(W, 0.05, L, M(0xb01e24)); return place(m, { ...p, y: p.y + 0.08 }, face); }
  // a big sign flat on the grass (read from above)
  function groundSign(p, txt, col = '#8a5a2a', w = 9, face = 0) { const sg = new THREE.Mesh(new THREE.PlaneGeometry(w, w * 0.28), new THREE.MeshBasicMaterial({ map: signTex(txt, null, col, 1024, 288) })); sg.rotation.x = -Math.PI / 2; const grp = new THREE.Group(); sg.position.y = 0.15; grp.add(sg); return place(grp, p, face); }
